package com.gregtech.gregtech.content.multiblock;
import java.util.*;import net.minecraft.world.level.block.Block;import net.neoforged.neoforge.registries.*;import com.gregtech.gregtech.registry.GTMultiblocks;
public final class LargeMachineParts {private LargeMachineParts(){}public static Block block(int id){var holder=find(id);if(holder==null)throw new IllegalArgumentException("Missing native original structural part "+id);return holder.get();}public static DeferredHolder<Block,Block> find(int id){return GTMultiblocks.findPart(id);}public static java.util.List<DeferredHolder<Block,Block>> blocks(){return GTMultiblocks.parts();}public static Integer tint(Block block){for(var part:SharedLargeMachineParts.DEFINITIONS){var holder=find(part.originalId());if(holder!=null&&holder.isBound()&&holder.get()==block)return com.gregtech.gregtech.api.material.GTMaterialRegistry.get(part.material()).getColor();}return null;}}
